const experiments={
 primase:{name:'引物酶',setup:'实验从 25% 进程开始：前导链及第一个冈崎片段已有引物。此时关闭引物酶，已有引物保留。',question:'接下来，新的冈崎片段还能起始吗？',options:['不能起始，但已有引物的新链仍可延伸','所有新链都会立刻停止延伸','可以起始，DNA 聚合酶会自己制造引物'],correct:0,result:'已有引物支持前导链和第一个冈崎片段继续延伸；后续片段缺少新的引物，因此无法起始。引物酶负责提供起点，DNA 聚合酶负责延伸已有起点。',observe:'追踪橙色片段：第一个可延伸，后续片段不会出现。绿色前导链已有起始引物。'},
 ligase:{name:'连接酶',setup:'实验从 25% 进程开始，关闭 DNA 连接酶。引物形成、DNA 延伸、RNA 引物移除和 DNA 替换仍正常进行。',question:'已复制区域最终最可能出现什么？',options:['DNA 片段无法形成','片段形成并完成引物替换，但骨架断口未封闭','RNA 引物一直保留，无法被 DNA 替换'],correct:1,result:'冈崎片段仍能合成，引物也能被 DNA 替换；连接酶缺失使相邻 DNA 之间的骨架断口（nick）保留。红圈强调的是缺少磷酸二酯键，不是一段核苷酸消失。',observe:'到末尾观察橙色链上的红圈：引物已被替换，但相邻片段间的骨架断口仍在。'}
};
function lockControls(locked){$('play').disabled=locked;$('timeline').disabled=locked;$('restart').disabled=experiment.mode!=='normal';$('next').disabled=experiment.mode!=='normal';[...$('steps').children].forEach(b=>b.disabled=experiment.mode!=='normal')}
function selectExperiment(mode){playing=false;experiment.mode=mode;experiment.started=false;experiment.comparison=false;experiment.prediction=null;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===mode));$('experimentBody').hidden=mode==='normal';$('experimentResult').hidden=true;$('compareExperiment').hidden=true;$('runExperiment').disabled=true;$('runExperiment').textContent='提交预测并运行';$('predictionOptions').replaceChildren();$('play').textContent='播放';lockControls(mode!=='normal');if(mode!=='normal'){const e=experiments[mode];$('experimentSetup').textContent=e.setup;$('predictionQuestion').textContent=e.question;e.options.forEach((text,i)=>{let label=document.createElement('label'),radio=document.createElement('input');radio.type='radio';radio.name='prediction';radio.value=i;radio.onchange=()=>{experiment.prediction=i;$('runExperiment').disabled=false};label.append(radio,document.createTextNode(text));$('predictionOptions').append(label)})}stage=-1;setProgress(mode==='normal'?0:25)}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>selectExperiment(b.dataset.mode));
$('runExperiment').onclick=()=>{if(experiment.prediction===null)return;experiment.started=true;experiment.comparison=false;playing=false;$('prediction').disabled=true;$('experimentResult').hidden=true;$('compareExperiment').hidden=true;lockControls(false);stage=-1;setProgress(25);playing=true;$('play').textContent='暂停';$('runExperiment').textContent='重新运行实验'};
$('compareExperiment').onclick=()=>{experiment.comparison=!experiment.comparison;stage=-1;setProgress(progress)};
window.updateExperiment=()=>{const mode=experiment.mode,e=experiments[mode];$('modelCondition').textContent=mode==='normal'?'正常复制':experiment.comparison?'正常对照 · 相同进程':'实验条件 · 关闭'+e.name;if(mode==='normal'){$('prediction').disabled=false;return}if(!experiment.started){$('prediction').disabled=false;$('experimentStatus').textContent='先选一个预测，再运行模型。';return}const complete=progress>=100;$('experimentStatus').textContent=complete?'观察完成：切换对照，比较同一进程。':experiment.comparison?'正在查看正常对照。':'观察模型，也可暂停或拖动时间轴。';$('compareExperiment').hidden=false;$('compareExperiment').textContent=experiment.comparison?'返回实验条件':'查看正常对照';$('experimentResult').hidden=!complete;if(complete)$('experimentResult').textContent=(experiment.prediction===e.correct?'你的预测正确。':'观察结果与你的预测不同。')+e.result;if(!experiment.comparison){$('stepText').textContent=stage<2?e.setup:stage===2?(mode==='primase'?'只有已获得引物的新链可继续延伸；新的冈崎片段无法起始。':'前导链与冈崎片段继续合成。关闭连接酶不会直接阻止 DNA 聚合酶延伸新链。'):e.result;$('observe').textContent=e.observe}};
selectExperiment('normal');
